import React, { useState, useEffect } from 'react';
import { collection, onSnapshot, doc, updateDoc, deleteDoc, addDoc, setDoc } from 'firebase/firestore';
import { db } from './firebase';
import * as XLSX from 'xlsx';
import { DEPARTMENTS } from './departments'; // departments.js import

const SuperAdminPage = ({ onNavigate }) => {
  const [departments, setDepartments] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({});

  // 신규 학과 추가용 상태
  const [newDept, setNewDept] = useState({
    id: '',
    name: '',
    password: '0000',
    college: ''
  });

  // 학과 목록 불러오기
  useEffect(() => {
    const deptRef = collection(db, "departments");
    const unsubscribe = onSnapshot(deptRef, (snapshot) => {
      const deptList = snapshot.docs.map(doc => ({
        docId: doc.id,
        ...doc.data()
      }));
      deptList.sort((a, b) => (a.college || '').localeCompare(b.college || ''));
      setDepartments(deptList);
    });

    return () => unsubscribe();
  }, []);

  // 학과 추가
  const handleAddDepartment = async () => {
    if (!newDept.id.trim() || !newDept.name.trim()) {
      alert("학과 ID와 이름을 모두 입력해주세요!");
      return;
    }

    // ID 중복 체크
    const exists = departments.find(d => d.id === newDept.id);
    if (exists) {
      alert("이미 존재하는 학과 ID입니다!");
      return;
    }

    try {
      // departments 컬렉션에 학과 ID를 문서 ID로 사용
      await setDoc(doc(db, "departments", newDept.id), {
        id: newDept.id,
        name: newDept.name,
        password: newDept.password || '0000',
        college: newDept.college || '',
        createdAt: new Date()
      });

      alert(`${newDept.name} 학과가 추가되었습니다!`);
      setNewDept({ id: '', name: '', password: '0000', college: '' });
    } catch (e) {
      console.error(e);
      alert("학과 추가 중 오류가 발생했습니다.");
    }
  };

  // 엑셀 파일 업로드 핸들러
  const handleExcelUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    try {
      const data = await file.arrayBuffer();
      const workbook = XLSX.read(data);
      const worksheet = workbook.Sheets[workbook.SheetNames[0]];
      const jsonData = XLSX.utils.sheet_to_json(worksheet);

      console.log("읽어온 엑셀 데이터:", jsonData);

      // 데이터 검증 및 변환
      const validDepartments = [];
      const errors = [];

      jsonData.forEach((row, index) => {
        const rowNum = index + 2; // 엑셀 행 번호 (헤더 제외)

        // 필수 필드 확인
        if (!row.id || !row.name) {
          errors.push(`${rowNum}번 행: ID와 이름은 필수입니다.`);
          return;
        }

        // ID 중복 체크
        const exists = departments.find(d => d.id === row.id);
        if (exists) {
          errors.push(`${rowNum}번 행: "${row.id}" ID가 이미 존재합니다.`);
          return;
        }

        // 이미 추가 목록에 있는지 체크
        const duplicate = validDepartments.find(d => d.id === row.id);
        if (duplicate) {
          errors.push(`${rowNum}번 행: "${row.id}" ID가 엑셀 내에서 중복됩니다.`);
          return;
        }

        validDepartments.push({
          id: String(row.id).trim(),
          name: String(row.name).trim(),
          password: row.password ? String(row.password).trim() : '0000',
          college: row.college ? String(row.college).trim() : ''
        });
      });

      // 오류가 있으면 확인 후 진행 여부 결정
      if (errors.length > 0) {
        const continueUpload = window.confirm(
          `⚠️ 다음 오류가 발견되었습니다:\n\n${errors.join('\n')}\n\n` +
          `오류가 있는 행을 제외하고 ${validDepartments.length}개 학과를 추가하시겠습니까?`
        );
        if (!continueUpload) {
          e.target.value = ''; // 파일 선택 초기화
          return;
        }
      }

      if (validDepartments.length === 0) {
        alert("추가할 수 있는 유효한 학과 데이터가 없습니다.");
        e.target.value = '';
        return;
      }

      // 확인 메시지
      const confirm = window.confirm(
        `📊 ${validDepartments.length}개의 학과를 추가하시겠습니까?\n\n` +
        validDepartments.map(d => `- ${d.name} (${d.id})`).join('\n')
      );

      if (!confirm) {
        e.target.value = '';
        return;
      }

      // Firebase에 일괄 추가
      let successCount = 0;
      let failCount = 0;

      for (const dept of validDepartments) {
        try {
          await setDoc(doc(db, "departments", dept.id), {
            ...dept,
            createdAt: new Date()
          });
          successCount++;
        } catch (error) {
          console.error(`${dept.id} 추가 실패:`, error);
          failCount++;
        }
      }

      alert(
        `✅ 업로드 완료!\n\n` +
        `성공: ${successCount}개\n` +
        `실패: ${failCount}개`
      );

      e.target.value = ''; // 파일 선택 초기화
    } catch (error) {
      console.error("엑셀 처리 오류:", error);
      alert("엑셀 파일 처리 중 오류가 발생했습니다.");
      e.target.value = '';
    }
  };

  // 엑셀 템플릿 다운로드
  const downloadExcelTemplate = () => {
    const template = [
      {
        id: "ai_business",
        name: "AI경영학과",
        password: "0000",
        college: "엔디컷국제대학"
      },
      {
        id: "global_railway",
        name: "글로벌철도학과",
        password: "1234",
        college: "철도물류대학"
      },
      {
        id: "computer_sw",
        name: "컴퓨터·소프트웨어전공",
        password: "0000",
        college: "소프트웨어융합대학"
      }
    ];

    const ws = XLSX.utils.json_to_sheet(template);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "학과목록");

    // 컬럼 너비 설정
    ws['!cols'] = [
      { wch: 20 }, // id
      { wch: 30 }, // name
      { wch: 10 }, // password
      { wch: 25 }  // college
    ];

    XLSX.writeFile(wb, "학과_업로드_템플릿.xlsx");
  };

  // 현재 학과 목록 엑셀 다운로드
  const downloadCurrentDepartments = () => {
    if (departments.length === 0) {
      alert("다운로드할 학과 데이터가 없습니다.");
      return;
    }

    const exportData = departments.map(dept => ({
      id: dept.id,
      name: dept.name,
      password: dept.password || '0000',
      college: dept.college || ''
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "학과목록");

    // 컬럼 너비 설정
    ws['!cols'] = [
      { wch: 20 }, // id
      { wch: 30 }, // name
      { wch: 10 }, // password
      { wch: 25 }  // college
    ];

    const today = new Date().toISOString().split('T')[0];
    XLSX.writeFile(wb, `학과목록_${today}.xlsx`);
  };

  // departments.js → Firebase 마이그레이션
  const migrateDepartmentsFromJS = async () => {
    const confirm = window.confirm(
      `🔄 departments.js 파일의 ${DEPARTMENTS.length}개 학과를 Firebase로 마이그레이션하시겠습니까?\n\n` +
      `⚠️ 주의: 이미 존재하는 학과는 덮어쓰기됩니다!`
    );

    if (!confirm) return;

    let successCount = 0;
    let failCount = 0;
    const results = [];

    for (const dept of DEPARTMENTS) {
      try {
        await setDoc(doc(db, "departments", dept.id), {
          id: dept.id,
          name: dept.name,
          password: dept.password || '0000',
          college: dept.college || '',
          createdAt: new Date()
        });
        
        successCount++;
        results.push(`✅ ${dept.name} (${dept.college})`);
      } catch (error) {
        failCount++;
        results.push(`❌ ${dept.name} - 오류: ${error.message}`);
        console.error(`❌ ${dept.name} 추가 실패:`, error);
      }
    }

    console.log("📊 마이그레이션 결과:", results);

    alert(
      `🎉 마이그레이션 완료!\n\n` +
      `성공: ${successCount}개\n` +
      `실패: ${failCount}개`
    );
  };

  // 학과 삭제
  const handleDeleteDepartment = async (deptId, deptName) => {
    const confirm = window.confirm(
      `⚠️ 경고: ${deptName} 학과를 삭제하시겠습니까?\n\n` +
      `이 학과에 속한 교수님과 강의 데이터는 삭제되지 않지만,\n` +
      `더 이상 이 학과로 필터링할 수 없게 됩니다.`
    );

    if (!confirm) return;

    try {
      await deleteDoc(doc(db, "departments", deptId));
      alert("삭제되었습니다.");
    } catch (e) {
      console.error(e);
      alert("삭제 중 오류가 발생했습니다.");
    }
  };

  // 수정 모드 시작
  const startEditing = (dept) => {
    setEditingId(dept.docId);
    setEditForm({
      id: dept.id,
      name: dept.name,
      password: dept.password || '0000',
      college: dept.college || ''
    });
  };

  // 수정 취소
  const cancelEditing = () => {
    setEditingId(null);
    setEditForm({});
  };

  // 수정 저장
  const saveEdit = async (docId) => {
    if (!editForm.name.trim()) {
      alert("학과 이름을 입력해주세요!");
      return;
    }

    try {
      await updateDoc(doc(db, "departments", docId), {
        name: editForm.name,
        password: editForm.password || '0000',
        college: editForm.college || '',
        updatedAt: new Date()
      });
      alert("수정되었습니다.");
      setEditingId(null);
      setEditForm({});
    } catch (e) {
      console.error(e);
      alert("수정 중 오류가 발생했습니다.");
    }
  };

  // 단과대학별 그룹핑
  const groupedByCollege = departments.reduce((acc, dept) => {
    const college = dept.college || '기타';
    if (!acc[college]) acc[college] = [];
    acc[college].push(dept);
    return acc;
  }, {});

  return (
    <div style={{ padding: '30px', maxWidth: '1400px', margin: '0 auto' }}>
      <button 
        onClick={() => onNavigate('list')}
        style={{ marginBottom: '20px', padding: '10px 20px', cursor: 'pointer', border: '1px solid #ccc', background: '#fff', borderRadius: '5px' }}
      >
        ⬅️ 메인으로 돌아가기
      </button>

      <h1 style={{ color: '#d32f2f', borderBottom: '3px solid #d32f2f', paddingBottom: '15px' }}>
        🔐 수퍼관리자 - 학과 관리
      </h1>

      {/* departments.js 마이그레이션 버튼 */}
      <div style={{ backgroundColor: '#fff3cd', padding: '15px', borderRadius: '8px', marginBottom: '20px', border: '2px solid #ffc107' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h4 style={{ margin: '0 0 5px 0', color: '#856404' }}>
              🔄 departments.js 파일에서 가져오기
            </h4>
            <p style={{ margin: 0, fontSize: '0.9rem', color: '#666' }}>
              기존 departments.js 파일의 {DEPARTMENTS.length}개 학과 데이터를 Firebase로 마이그레이션합니다.
            </p>
          </div>
          <button
            onClick={migrateDepartmentsFromJS}
            style={{
              padding: '12px 20px',
              backgroundColor: '#ffc107',
              color: '#000',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer',
              fontWeight: 'bold',
              fontSize: '0.95rem',
              whiteSpace: 'nowrap'
            }}
          >
            🚀 지금 마이그레이션
          </button>
        </div>
      </div>

      {/* 신규 학과 추가 섹션 */}
      <div style={{ backgroundColor: '#fff3e0', padding: '25px', borderRadius: '10px', marginBottom: '30px', border: '2px solid #ff9800' }}>
        <h3 style={{ marginTop: 0, color: '#e65100' }}>➕ 신규 학과 추가</h3>
        
        {/* 엑셀 업로드 섹션 */}
        <div style={{ backgroundColor: '#e8f5e9', padding: '15px', borderRadius: '8px', marginBottom: '20px', border: '1px solid #4caf50' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
            <h4 style={{ margin: 0, color: '#2e7d32' }}>📊 엑셀 일괄 업로드</h4>
            <button
              onClick={downloadExcelTemplate}
              style={{ 
                padding: '8px 15px', 
                backgroundColor: '#4caf50', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: 'bold'
              }}
            >
              📥 템플릿 다운로드
            </button>
          </div>
          
          <div style={{ fontSize: '0.85rem', color: '#666', marginBottom: '10px' }}>
            💡 여러 학과를 한 번에 추가하려면 엑셀 파일을 업로드하세요.<br/>
            엑셀 파일 형식: <strong>id</strong> | <strong>name</strong> | <strong>password</strong> | <strong>college</strong>
          </div>

          <input
            type="file"
            accept=".xlsx,.xls"
            onChange={handleExcelUpload}
            style={{ 
              padding: '10px', 
              border: '2px dashed #4caf50', 
              borderRadius: '4px',
              width: '100%',
              backgroundColor: 'white',
              cursor: 'pointer'
            }}
          />
        </div>

        <div style={{ textAlign: 'center', margin: '15px 0', color: '#999', fontWeight: 'bold' }}>
          ─────── 또는 ───────
        </div>

        {/* 개별 추가 폼 */}
        <h4 style={{ marginTop: '20px', marginBottom: '15px', color: '#e65100' }}>✍️ 개별 입력</h4>
        
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '15px', marginBottom: '15px' }}>
          <div>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>학과 ID (영문)</label>
            <input
              type="text"
              placeholder="예: ai_business"
              value={newDept.id}
              onChange={(e) => setNewDept({ ...newDept, id: e.target.value })}
              style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '4px' }}
            />
            <small style={{ color: '#666' }}>* 영문 소문자, 숫자, 언더스코어(_)만 사용</small>
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>학과명 (한글)</label>
            <input
              type="text"
              placeholder="예: AI경영학과"
              value={newDept.name}
              onChange={(e) => setNewDept({ ...newDept, name: e.target.value })}
              style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '4px' }}
            />
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '15px' }}>
          <div>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>소속 단과대학</label>
            <input
              type="text"
              placeholder="예: 엔디컷국제대학"
              value={newDept.college}
              onChange={(e) => setNewDept({ ...newDept, college: e.target.value })}
              style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '4px' }}
            />
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>비밀번호</label>
            <input
              type="text"
              placeholder="기본값: 0000"
              value={newDept.password}
              onChange={(e) => setNewDept({ ...newDept, password: e.target.value })}
              style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '4px' }}
            />
            <small style={{ color: '#666' }}>* 해당 학과 조교용 비밀번호</small>
          </div>
        </div>

        <button
          onClick={handleAddDepartment}
          style={{ width: '100%', padding: '15px', backgroundColor: '#ff9800', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '1.1rem' }}
        >
          ✅ 학과 추가하기
        </button>
      </div>

      {/* 학과 목록 */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3 style={{ margin: 0 }}>📚 등록된 학과 목록 (총 {departments.length}개)</h3>
          <button
            onClick={downloadCurrentDepartments}
            style={{
              padding: '10px 20px',
              backgroundColor: '#2196f3',
              color: 'white',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer',
              fontWeight: 'bold',
              fontSize: '0.9rem'
            }}
          >
            📊 현재 목록 엑셀 다운로드
          </button>
        </div>
        
        {Object.keys(groupedByCollege).sort().map(college => (
          <div key={college} style={{ marginBottom: '30px' }}>
            <h4 style={{ 
              backgroundColor: '#e3f2fd', 
              padding: '10px 15px', 
              borderRadius: '5px', 
              color: '#1565c0',
              marginBottom: '15px'
            }}>
              🏛️ {college} ({groupedByCollege[college].length}개 학과)
            </h4>

            <div style={{ display: 'grid', gap: '15px' }}>
              {groupedByCollege[college].map(dept => (
                <div key={dept.docId} style={{ backgroundColor: 'white', border: '1px solid #ddd', borderRadius: '8px', padding: '20px' }}>
                  {editingId === dept.docId ? (
                    // 수정 모드
                    <div>
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr 1fr 1fr', gap: '10px', marginBottom: '10px' }}>
                        <div>
                          <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '3px', color: '#666' }}>학과 ID</label>
                          <input
                            value={editForm.id}
                            disabled
                            style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '4px', backgroundColor: '#f5f5f5' }}
                          />
                        </div>
                        <div>
                          <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '3px', color: '#666' }}>학과명</label>
                          <input
                            value={editForm.name}
                            onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                            style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                          />
                        </div>
                        <div>
                          <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '3px', color: '#666' }}>단과대학</label>
                          <input
                            value={editForm.college}
                            onChange={(e) => setEditForm({ ...editForm, college: e.target.value })}
                            style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                          />
                        </div>
                        <div>
                          <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '3px', color: '#666' }}>비밀번호</label>
                          <input
                            value={editForm.password}
                            onChange={(e) => setEditForm({ ...editForm, password: e.target.value })}
                            style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                          />
                        </div>
                      </div>

                      <div style={{ display: 'flex', gap: '10px' }}>
                        <button
                          onClick={() => saveEdit(dept.docId)}
                          style={{ flex: 1, padding: '10px', backgroundColor: '#2196f3', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold' }}
                        >
                          💾 저장
                        </button>
                        <button
                          onClick={cancelEditing}
                          style={{ flex: 1, padding: '10px', backgroundColor: '#9e9e9e', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold' }}
                        >
                          ❌ 취소
                        </button>
                      </div>
                    </div>
                  ) : (
                    // 일반 보기 모드
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div style={{ flex: 1 }}>
                        <div style={{ display: 'flex', gap: '15px', alignItems: 'center', marginBottom: '8px' }}>
                          <span style={{ 
                            backgroundColor: '#e0e0e0', 
                            padding: '4px 12px', 
                            borderRadius: '12px', 
                            fontSize: '0.85rem',
                            fontFamily: 'monospace',
                            color: '#424242'
                          }}>
                            {dept.id}
                          </span>
                          <h4 style={{ margin: 0, fontSize: '1.2rem', color: '#212121' }}>
                            {dept.name}
                          </h4>
                          <span style={{ 
                            backgroundColor: '#fff9c4', 
                            padding: '4px 10px', 
                            borderRadius: '12px', 
                            fontSize: '0.8rem',
                            color: '#f57f17'
                          }}>
                            🔑 {dept.password || '0000'}
                          </span>
                        </div>
                      </div>
                      
                      <div style={{ display: 'flex', gap: '8px' }}>
                        <button
                          onClick={() => startEditing(dept)}
                          style={{ padding: '8px 15px', backgroundColor: '#2196f3', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontSize: '0.9rem' }}
                        >
                          ✏️ 수정
                        </button>
                        <button
                          onClick={() => handleDeleteDepartment(dept.docId, dept.name)}
                          style={{ padding: '8px 15px', backgroundColor: '#f44336', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontSize: '0.9rem' }}
                        >
                          🗑️ 삭제
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        ))}

        {departments.length === 0 && (
          <div style={{ textAlign: 'center', padding: '40px', color: '#999' }}>
            아직 등록된 학과가 없습니다.
          </div>
        )}
      </div>

      {/* 안내 메시지 */}
      <div style={{ marginTop: '40px', padding: '20px', backgroundColor: '#f5f5f5', borderRadius: '8px', border: '1px solid #ddd' }}>
        <h4 style={{ marginTop: 0, color: '#d32f2f' }}>⚠️ 주의사항</h4>
        <ul style={{ margin: 0, paddingLeft: '20px', color: '#666' }}>
          <li>학과 ID는 한 번 생성하면 변경할 수 없습니다.</li>
          <li>학과 삭제 시 해당 학과의 교수/강의 데이터는 삭제되지 않습니다.</li>
          <li>departments.js 파일과 Firebase의 departments 컬렉션이 동기화되어야 합니다.</li>
        </ul>
      </div>
    </div>
  );
};

export default SuperAdminPage;