// src/App.js
import React, { useState, useEffect } from 'react';
import CourseList from './CourseList';
import AdminPage from './AdminPage';
import SummaryPage from './SummaryPage';
import SuperAdminPage from './SuperAdminPage';  // ← 수퍼관리자 페이지 추가
import { collection, onSnapshot } from 'firebase/firestore';
import { db } from './firebase';

// 수퍼관리자 비밀번호 (보안을 위해 환경변수로 관리하는 것이 좋습니다)
const SUPER_ADMIN_PASSWORD = "wsu2025!@#";  // ← 원하는 비밀번호로 변경하세요

function App() {
  const [currentPage, setCurrentPage] = useState('list');

  // 1. 년도/학기 선택 상태 (기본값: 2026년 1학기)
  const [year, setYear] = useState("2026");
  const [term, setTerm] = useState("spring");
  
  // 2. 학과 목록 및 선택 상태
  const [departments, setDepartments] = useState([]);
  const [selectedDept, setSelectedDept] = useState("");

  // Firebase에서 학과 목록 불러오기
  useEffect(() => {
    const deptRef = collection(db, "departments");
    const unsubscribe = onSnapshot(deptRef, (snapshot) => {
      const deptList = snapshot.docs.map(doc => ({
        docId: doc.id,
        ...doc.data()
      }));
      deptList.sort((a, b) => (a.college || '').localeCompare(b.college || ''));
      setDepartments(deptList);
      
      // 첫 번째 학과를 기본 선택
      if (deptList.length > 0 && !selectedDept) {
        setSelectedDept(deptList[0].id);
      }
    });

    return () => unsubscribe();
  }, []);

  // DB 컬렉션 이름 조합 (예: 2026_spring)
  const semesterId = `${year}_${term}`;
  
  // 현재 선택된 학과 정보
  const currentDept = departments.find(d => d.id === selectedDept);

  // 화면 전환 함수
  const handleNavigate = (page) => {
    setCurrentPage(page);
  };

  // 수퍼관리자 접근 확인
  const handleSuperAdminAccess = () => {
    const password = prompt("🔐 수퍼관리자 비밀번호:");
    if (password === null) return; // 취소 버튼
    
    if (password === SUPER_ADMIN_PASSWORD) {
      setCurrentPage('superadmin');
    } else {
      alert("비밀번호가 틀렸습니다.");
    }
  };

  // 학과별 비밀번호 확인
  const verifyDepartmentPassword = (inputPassword) => {
    if (!currentDept) return false;
    
    // 비밀번호가 설정되지 않은 경우
    if (!currentDept.password || currentDept.password === "") {
      return inputPassword === "0000"; // 기본 비밀번호
    }
    
    return currentDept.password === inputPassword;
  };

  const handleAdminAccess = () => {
    const password = prompt("🔐 관리자 비밀번호:");
    if (password === null) return; // 취소 버튼
    
    // 학과별 비밀번호 검증
    if (verifyDepartmentPassword(password)) {
      const choice = prompt("1. 관리자 모드\n2. 시수 현황 (통계)");
      if (choice === "1") handleNavigate('admin');
      else if (choice === "2") handleNavigate('summary');
    } else {
      alert(`비밀번호가 틀렸습니다.\n\n💡 힌트:\n- ${currentDept?.name}: ${currentDept?.password || '0000'}\n- 수퍼관리자는 상단 🔧 버튼을 사용하세요`);
    }
  };

  return (
    <div style={{ fontFamily: 'sans-serif' }}>
      
      {/* 상단 통합 컨트롤 바 (년도/학기/학과 선택) */}
      <div style={{ 
        backgroundColor: '#333', color: 'white', padding: '15px 20px', 
        display: 'flex', flexDirection: 'column', gap: '10px'
      }}>
        {/* 첫 번째 줄: 학기 설정 + 수퍼관리자 버튼 */}
        <div style={{ display:'flex', gap:'10px', alignItems:'center', flexWrap:'wrap', justifyContent:'space-between' }}>
          <div style={{ display:'flex', gap:'10px', alignItems:'center', flexWrap:'wrap' }}>
            <span style={{ fontSize:'1.2rem', fontWeight:'bold' }}>📅 학기:</span>
            
            {/* 년도 선택 */}
            <select 
              value={year} 
              onChange={(e) => setYear(e.target.value)}
              style={{ padding:'5px', borderRadius:'4px', fontWeight:'bold' }}
            >
              <option value="2025">2025년</option>
              <option value="2026">2026년</option>
              <option value="2027">2027년</option>
              <option value="2028">2028년</option>
            </select>

            {/* 학기 선택 */}
            <select 
              value={term} 
              onChange={(e) => setTerm(e.target.value)}
              style={{ padding:'5px', borderRadius:'4px', fontWeight:'bold' }}
            >
              <option value="spring">1학기 (Spring)</option>
              <option value="summer">여름학기 (Summer)</option>
              <option value="fall">2학기 (Fall)</option>
              <option value="winter">겨울학기 (Winter)</option>
            </select>
          </div>

          {/* 수퍼관리자 버튼 */}
          <button
            onClick={handleSuperAdminAccess}
            style={{
              padding: '8px 15px',
              backgroundColor: '#d32f2f',
              color: 'white',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer',
              fontWeight: 'bold',
              fontSize: '0.9rem'
            }}
          >
            🔧 수퍼관리자
          </button>
        </div>

        {/* 두 번째 줄: 학과 선택 */}
        <div style={{ display:'flex', gap:'10px', alignItems:'center', flexWrap:'wrap' }}>
          <span style={{ fontSize:'1.2rem', fontWeight:'bold' }}>🏫 학과:</span>
          
          {/* 학과 선택 */}
          <select 
            value={selectedDept} 
            onChange={(e) => setSelectedDept(e.target.value)}
            style={{ padding:'5px', borderRadius:'4px', fontWeight:'bold', minWidth:'300px' }}
          >
            {departments.map(dept => (
              <option key={dept.id} value={dept.id}>
                {dept.college ? `[${dept.college}] ${dept.name}` : dept.name}
              </option>
            ))}
          </select>

          <span style={{ marginLeft:'10px', color:'#aaa', fontSize:'0.85rem' }}>
            현재: {year}년 {term === 'spring' ? '1학기' : term === 'summer' ? '여름학기' : term === 'fall' ? '2학기' : '겨울학기'} / {currentDept?.name}
          </span>
        </div>
      </div>

      {/* 메인 화면 영역 */}
      <div style={{ padding: '0' }}>
        {currentPage === 'list' && (
          <CourseList 
            onNavigate={handleNavigate}
            onAdminAccess={handleAdminAccess}  // ← 관리자 접근 함수 전달
            semesterId={semesterId}
            departmentId={selectedDept}
            departmentName={currentDept?.name}
          />
        )}
        
        {currentPage === 'admin' && (
          <div style={{ padding: '20px' }}>
             <button 
              onClick={() => setCurrentPage('list')}
              style={{ marginBottom:'20px', padding:'10px', cursor:'pointer', border:'1px solid #ccc', background:'#fff', borderRadius:'5px' }}
            >
              ⬅️ 메인으로 돌아가기
            </button>
            <AdminPage 
              semesterId={semesterId}
              departmentId={selectedDept}
              departmentName={currentDept?.name}
            />
          </div>
        )}

        {currentPage === 'summary' && (
          <SummaryPage 
            onNavigate={handleNavigate} 
            semesterId={semesterId}
            departmentId={selectedDept}
            departmentName={currentDept?.name}
          />
        )}

        {currentPage === 'superadmin' && (
          <SuperAdminPage 
            onNavigate={handleNavigate}
          />
        )}
      </div>
    </div>
  );
}

export default App;